import javax.swing.*;public class IconCheck {public static void main(String[]a)throws Exception{SwingUtilities.invokeAndWait(()->{com.formdev.flatlaf.FlatLightLaf.setup();var f=new QuizoraApp.Ui.Auth.loginForm();try{var member=f.getClass().getDeclaredField("passwordField");member.setAccessible(true);var p=(JPasswordField)member.get(f);for(var c:p.getComponents())if(c instanceof JToggleButton b){if(!b.getIcon().toString().endsWith("eye_closed.png")||!b.getSelectedIcon().toString().endsWith("eye.png"))throw new AssertionError();b.doClick();if(p.getEchoChar()!=0)throw new AssertionError();b.doClick();if(p.getEchoChar()==0)throw new AssertionError();System.out.println("Custom eye icons and reveal/hide passed");return;}throw new AssertionError("Missing toggle");}catch(ReflectiveOperationException e){throw new RuntimeException(e);}finally{f.dispose();}});}}
